CREATE TABLE IF NOT EXISTS "ai_ppt" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL,
    "title" varchar(255) NOT NULL DEFAULT '',
    "source" tinyint NOT NULL,
    "content" varchar(65535) DEFAULT NULL,
    "file_url" varchar(1024) DEFAULT NULL,
    "prompt" varchar(1024) NOT NULL DEFAULT '',
    "mode" tinyint NOT NULL,
    "language" varchar(16) NOT NULL DEFAULT 'zh-CN',
    "page_count" int NOT NULL,
    "chat_model_id" bigint NOT NULL,
    "image_model_id" bigint NOT NULL,
    "slides" varchar(65535) DEFAULT NULL,
    "cover_url" varchar(1024) DEFAULT NULL,
    "slide_count" int NOT NULL DEFAULT 0,
    "finish_count" int NOT NULL DEFAULT 0,
    "status" tinyint NOT NULL,
    "attempt" int NOT NULL DEFAULT 0,
    "error_message" varchar(1024) DEFAULT NULL,
    "finish_time" timestamp DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI PPT 表';

CREATE TABLE IF NOT EXISTS "ai_speech" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL,
    "model_id" bigint NOT NULL,
    "platform" varchar(32) NOT NULL,
    "model" varchar(64) NOT NULL,
    "api_key_id" bigint NOT NULL,
    "input_text" varchar(65535) NOT NULL,
    "voice" varchar(64) NOT NULL,
    "format" varchar(16) NOT NULL,
    "speed" decimal(4, 2) DEFAULT NULL,
    "status" tinyint NOT NULL,
    "task_id" varchar(128) DEFAULT NULL,
    "audio_url" varchar(1024) DEFAULT NULL,
    "audio_size" int DEFAULT NULL,
    "error_message" varchar(1024) DEFAULT NULL,
    "finish_time" timestamp DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 语音表';

CREATE TABLE IF NOT EXISTS "ai_write" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "user_id" bigint NOT NULL,
    "type" int DEFAULT NULL,
    "platform" varchar(255) NOT NULL,
    "model_id" bigint NOT NULL,
    "model" varchar(255) NOT NULL,
    "prompt" varchar(65535) NOT NULL,
    "generated_content" varchar(65535) DEFAULT NULL,
    "original_content" varchar(65535) DEFAULT NULL,
    "length" tinyint DEFAULT NULL,
    "format" tinyint DEFAULT NULL,
    "tone" tinyint DEFAULT NULL,
    "language" tinyint DEFAULT NULL,
    "scene_params" varchar(1000) DEFAULT NULL,
    "error_message" varchar(255) DEFAULT NULL,
    "request_id" varchar(64) DEFAULT NULL,
    "input_tokens" bigint DEFAULT NULL,
    "output_tokens" bigint DEFAULT NULL,
    "total_tokens" bigint DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 写作表';

CREATE TABLE IF NOT EXISTS "ai_request_log" (
    "id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY,
    "request_id" varchar(64) NOT NULL,
    "user_id" bigint DEFAULT NULL,
    "biz_type" tinyint NOT NULL,
    "biz_id" bigint DEFAULT NULL,
    "platform" varchar(32) DEFAULT NULL,
    "model_id" bigint DEFAULT NULL,
    "model" varchar(64) DEFAULT NULL,
    "status" tinyint NOT NULL,
    "error_message" varchar(4096) DEFAULT NULL,
    "begin_time" timestamp DEFAULT NULL,
    "end_time" timestamp DEFAULT NULL,
    "duration" bigint DEFAULT NULL,
    "input_tokens" bigint DEFAULT NULL,
    "output_tokens" bigint DEFAULT NULL,
    "total_tokens" bigint DEFAULT NULL,
    "response_metadata" varchar(65535) DEFAULT NULL,
    "creator" varchar(64) DEFAULT '',
    "create_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updater" varchar(64) DEFAULT '',
    "update_time" timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "deleted" bit NOT NULL DEFAULT FALSE,
    "tenant_id" bigint NOT NULL DEFAULT 0,
    PRIMARY KEY ("id")
) COMMENT 'AI 请求日志表';
